
const menu=[['home','⌂','İş sırası','2'],['stock','▦','Ürün & stok',''],['goods','⇩','Gelen mal','1'],['purchases','▤','Alış faturaları','2'],['sales','▣','Satış terminali',''],['receipts','≡','Satış fişleri','3'],['customers','♙','Müşteriler',''],['suppliers','▧','Tedarikçiler',''],['collections','₺','Tahsilat',''],['supplier-payments','₺','Tedarikçi Ödeme',''],['count','⌗','Sayım & düzeltme','1'],['returns','↩','İadeler',''],['approvals','✓','Onaylar','2'],['settings','⚙','Ayarlar','']];
const terminalDevice=new URLSearchParams(location.search).has('terminal-device');if(terminalDevice)document.body.classList.add('terminal-device');
let current=menu.some(item=>item[0]===location.hash.slice(1))?location.hash.slice(1):'home', role='İlker · Ön muhasebe', stock=[['M-100','Triko bebek takımı','3–6 ay · 6’lı seri',24,10.5,'Aktif','Takım'],['M-142','Kapüşonlu tulum','6–12 ay · 6’lı seri',42,12,'Aktif','Tulum'],['M-208','Pamuklu body seti','0–3 ay · 8’li seri',18,8.2,'Az stok','Body'],['M-311','Kadife elbise takımı','2–3 yaş · 6’lı seri',96,15.8,'Aktif','Elbise'],['M-445','Desenli pijama takımı','3–4 yaş · 6’lı seri',7,11.4,'Kritik','Pijama']];
let saleCustomer='cash',saleDepot='Merkez',saleCompact=false,saleStage='edit',saleMessage='';
const saleCustomers={cash:'Peşin Dolar',alfa:'Alfa Kids · USD'};
let basket=[], navEl=document.getElementById('nav'), view=document.getElementById('view');
const htmlText=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>new Intl.NumberFormat('tr-TR',{minimumFractionDigits:2,maximumFractionDigits:2}).format(n);
function drawNav(){navEl.innerHTML=menu.map(([id,icon,label,badge])=>`<button class="${id===current?'active':''}" data-screen="${id}"><span class="ico">${icon}</span>${label}${window.MelisaPageCompletion?.[id]?'<span class="nav-complete" title="Örnek akış tamamlandı" aria-label="Örnek akış tamamlandı">✓</span>':''}${badge?`<span class="badge">${badge}</span>`:''}</button>`).join('');navEl.querySelectorAll('button').forEach(b=>b.onclick=()=>go(b.dataset.screen));document.getElementById('mobileScreen').value=current;}
function go(id){if(window.MelisaWorkingBeforeNavigate?.()===false)return;current=id;history.replaceState(null,'','#'+id);drawNav();render();document.getElementById('crumb').textContent=menu.find(x=>x[0]===id)?.[2]||'İş sırası';}
function title(kicker,h,sub,action=''){return `<div class="heading"><div><div class="eyebrow">${kicker}</div><h1>${h}</h1><p class="sub">${sub}</p></div><div class="actions">${action}</div></div>`}
function stat(label,value,small,warn=''){return `<div class="card stat ${warn}"><span class="dot"></span><div class="label">${label}</div><strong>${value}</strong><small>${small}</small></div>`}
function panel(head,body,more=''){return `<section class="card panel"><div class="panel-head"><h2>${head}</h2>${more}</div>${body}</section>`}
function badge(text,tone=''){return `<span class="pill ${tone}">${text}</span>`}
function tasks(rows){return `<div class="tasklist">${rows.map(([ic,h,s,p,t])=>`<div class="task"><div class="taskicon">${ic}</div><div><b>${h}</b><small>${s}</small></div>${badge(p,t)}</div>`).join('')}</div>`}
function productRows(){return stock.map((p,i)=>`<tr data-wf-click="wf1" data-wf-arg0="${i}"><td><div class="product"><div class="thumb">${p[0].slice(0,3)}</div><div><b>${htmlText(p[1])}</b><small>${p[0]} · ${htmlText(p[2])}</small></div></div></td><td>${p[3]} adet</td><td>${fmt(p[4])} USD</td><td>${p[5]==='Kritik'?badge(p[5],'red'):p[5]==='Az stok'?badge(p[5],'orange'):badge(p[5],'green')}</td><td>›</td></tr>`).join('')}
function render(){let pages={home:homePage,stock:stockPage,goods:goodsPage,purchases:purchasesPage,sales:salesPage,receipts:receiptsPage,customers:customersPage,collections:collectionsPage,count:countPage,returns:returnsPage,approvals:approvalsPage,settings:settingsPage};document.body.classList.toggle('stock-workspace',current==='stock');document.body.classList.toggle('home-workspace',current==='home');document.body.classList.toggle('trade-workspace',['sales','receipts','customers','collections','goods','purchases','suppliers','supplier-payments'].includes(current));view.innerHTML=['sales','receipts','customers','collections','goods','purchases','suppliers','supplier-payments'].includes(current)?'<section class="card panel" style="padding:20px"><p role="status">İşlem bilgileri açılıyor…</p></section>':(pages[current]||homePage)();document.dispatchEvent(new Event('workflow-render'));document.getElementById('crumb').textContent=menu.find(x=>x[0]===current)?.[2]||'İş sırası';}
function homePage(){return title('MELİSA ERP · İŞ SIRASI','Bugün sırada ne var?','Günlük işlerinizi ve işlem kısayollarını buradan takip edin.')+'<section class="card panel" style="padding:20px" aria-label="Bugünkü işler"><h2>Bugünkü işler</h2><p role="status">Günlük işler açılıyor…</p></section>'}
function stockPage(){return `${title('ÜRÜN KARTLARI','Ürün & stok','Ürünleri bulun; stok, barkod ve satış fiyatını kartında inceleyin.')}<div class="stock-split">${panel('Stok listesi','<p role="status" style="padding:20px">Katalog açılıyor…</p>')}<div id="productDetail" class="product-inspector"><section class="card inspector-empty"><h2>Ürün bilgileri</h2><p>Soldaki listeden bir ürün seçin.</p></section></div></div>`}
function goodsPage(){return `${title('MAL KABULÜ','Gelen mal','Kolileri say, barkod ve miktarı kaydet. İlker ürün kartlarını kontrol eder; kabul tamamlanınca stok bir kez artar.','<button class="btn primary" data-wf-click="wf9">＋ Yeni mal kabulü</button>')}<div class="grid stats">${stat('Sayım bekliyor','1 sevkiyat','Personel barkodları indiriyor','warn')}${stat('Muhasebe kontrolünde','2 sevkiyat','Stok henüz artmadı')}${stat('Fatura bekliyor','1 kabul · 48 adet','Alışa bağlanacak','warn')}${stat('Bugün kabul edilen','120 adet','Stok artışı tamamlandı')}</div><div class="grid two">${panel('Sevkiyat listesi',`<div class="listrows"><div class="rowitem"><div class="taskicon">⇩</div><div class="rowtext"><b>Concept · MK-00418</b><small>Bugün 07:12 · 120 adet · Sayım tamam</small></div>${badge('İlker kontrol edecek','orange')}</div><div class="rowitem"><div class="taskicon">⇩</div><div class="rowtext"><b>Noynoy · MK-00417</b><small>Bugün 07:04 · 48 adet · kısmi fatura</small></div>${badge('Fatura bekliyor','blue')}</div><div class="rowitem"><div class="taskicon">⇩</div><div class="rowtext"><b>Baby Rose · MK-00416</b><small>Dün · 96 adet · kart eşleşmesi bekliyor</small></div>${badge('Eşleştirme','orange')}</div></div>`)}${panel('Seçili kabul · MK-00418',`<div style="padding:16px"><div class="notice amber"><strong>Durum: Muhasebe kontrolünde.</strong> Fiziksel miktar onaylanana kadar stok 24 adet kalır.</div><div class="rowitem"><div class="thumb">M-100</div><div class="rowtext"><b>Triko bebek takımı · 120 adet</b><small>60 pembe barkod + 60 mavi barkod · aynı ürün kartı</small></div></div><p class="sub" style="margin:12px 0">Tamamlanınca: 24 → <b>144 adet</b><br>Fatura ayrı bağlanır; tedarikçi borcu faturada oluşur.</p><button class="btn primary" data-wf-click="wf10">Mal kabulünü tamamla</button></div>`,'<small>İlker görünümü</small>')}</div>`}
function purchasesPage(){return `${title('TEDARİKÇİ','Alış faturaları','Onaylı mal kabullerini faturaya bağla. Fatura girişi stok adedini ikinci kez artırmaz.','<button class="btn primary" data-wf-click="wf11">＋ Fatura gir</button>')}<div class="notice"><strong>Bağlantı kuralı:</strong> MK-00418 kabulünde 120 adet stokta. İlk fatura 72 adet için girilmiş; kalan 48 adet fatura bekliyor.</div>${panel('Fatura ve mal kabulü eşleştirme',`<div class="filters"><input class="search" placeholder="Fatura no veya tedarikçi ara"><select class="filter"><option>Fatura bekleyenler</option><option>Tümü</option></select></div><div class="tablewrap"><table><thead><tr><th>Tedarikçi / belge</th><th>Mal kabulü</th><th>Faturalanan</th><th>Kalan</th><th>Tutar</th><th>Durum</th></tr></thead><tbody><tr><td><b>Concept</b><br><small>Fatura C-2026-918</small></td><td>MK-00418</td><td>72 / 120 adet</td><td>48 adet</td><td>432 USD</td><td>${badge('Kısmi','orange')}</td></tr><tr><td><b>Noynoy</b><br><small>Fatura N-2026-441</small></td><td>MK-00417</td><td>48 / 48 adet</td><td>0</td><td>612 EUR</td><td>${badge('Bağlandı','green')}</td></tr></tbody></table></div>`,'<small>Örnek kayıtlar</small>')}<div style="height:14px"></div>${panel('Fatura ayrıntısında',tasks([['▤','Ürün ve miktar payını kabulden al','Aynı miktarı yeniden yazma','İlişkili satır','green'],['₺','Alış fiyatı, iskonto, KDV ve kuru gir','Toplam tutarı onaydan önce gör','Fatura toplamı','blue'],['✓','Onayla ve cari borcu oluştur','Stok miktarı değişmez','Bir kez kaydet','green']]))}`}
let saleFxRate='';
function saleCurrencyFor(id){return window.MelisaDemoCustomers?.list().find(c=>c.id===id)?.currency||'USD'}
function saleCurrency(){return saleCurrencyFor(saleCustomer)}
function salePriceCents(item){try{return window.MelisaReceiptPreview.priceInCurrency(Math.round(item.price*100),saleCurrency()==='USD'?'1':saleFxRate)}catch{return NaN}}
function saleMoney(cents){return Number.isFinite(cents)?fmt(cents/100)+' '+saleCurrency():'Kur gerekli'}
function updateSalePricing(){const total=document.getElementById('sale-total');if(total)total.textContent=saleMoney(salesTotal()*100);document.querySelectorAll('#basket tr').forEach((row,i)=>{const b=basket[i];if(!b)return;const price=row.querySelector('[data-label="Birim fiyat"]'),amount=row.querySelector('[data-label="Tutar"] b'),meta=row.querySelector('.sale-row-meta');if(price)price.textContent=saleMoney(salePriceCents(b));if(amount)amount.textContent=saleMoney(salePriceCents(b)*b.qty);if(meta)meta.textContent=saleMoney(salePriceCents(b))+' · Stok '+b.stock})}
function salesTotal(){const subtotal=basket.reduce((sum,b)=>sum+salePriceCents(b)*b.qty,0),rate=window.MelisaSaleDiscountBps||0;return rate>=0&&rate<=500?(subtotal-(rate<=300?Math.round(subtotal*rate/10000):0))/100:NaN}
function saleCount(){return basket.reduce((sum,b)=>sum+b.qty,0)}
function receiptTypeSummary(){const groups=new Map();for(const item of basket){const type=item.category||stock.find(p=>p[0]===item.code)?.[6]||'Türü belirtilmemiş';groups.set(type,(groups.get(type)||0)+item.qty)}const safe=text=>String(text).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));return `<section class="receipt-type-box" aria-label="Ürün türü özeti"><strong>Ürün türü özeti</strong><div>${[...groups].sort((a,b)=>b[1]-a[1]).map(([type,qty])=>`<span>${safe(type)} <b>${qty} adet</b></span>`).join('')}</div><small>Toplam ${saleCount()} adet · ${basket.length} ürün satırı</small></section>`}
function salesPage(){return `${title('SATIŞ EKİBİ · TASARIM ÖNİZLEMESİ','Satış terminali','USD / EUR / TRY örnek fişi · gerçek stok, cari ve tahsilat kaydı oluşturmaz.',`<button class="btn" data-wf-click="wf12">${saleCompact?'Bilgisayar görünümü':'El terminali görünümü'}</button>`)}<div class="term sale-shell ${saleCompact?'sale-compact':''}"><div class="terminal"><div class="termhead"><div><small>1 MÜŞTERİ · 2 ÜRÜNLER · 3 TAMAMLA</small><h2>${saleStage==='done'?'Örnek fiş tamamlandı':saleStage==='review'?'Fişi kontrol et':'Yeni satış'}</h2></div>${badge('Örnek','green')}</div>${saleStage==='edit'?`<div class="sale-fields"><label>Müşteri<select aria-label="Satış müşterisi" data-wf-change="wf13">${Object.entries(saleCustomers).map(([id,name])=>`<option value="${htmlText(id)}" ${saleCustomer===id?'selected':''}>${htmlText(name)} · ${saleCurrencyFor(id)}</option>`).join('')}</select></label>${saleCurrency()!=='USD'?`<label>Kur: 1 USD kaç ${saleCurrency()}?<input aria-label="Satış kuru" inputmode="decimal" value="${htmlText(saleFxRate)}" placeholder="Kuru girin" data-wf-input="wf14"></label><small>Ürün USD fiyatı bu kurla çevrilir; kur fişte saklanır.</small>`:''}</div><label for="scan" class="sale-scan-label">Barkod okut / Model kodu gir</label><div class="termsearch"><input id="scan" placeholder="Örnek: M-100" autocomplete="off"><button data-wf-click="wf15">Ekle ↵</button></div><div class="sale-feedback" role="status">${saleMessage||'Aynı ürün tekrar okutulursa miktarı bir artar.'}</div>`:`<div class="sale-summary"><b>${htmlText(saleCustomers[saleCustomer])}</b><span>${saleCurrency()}</span><span>${basket.length} kalem · ${saleCount()} adet</span></div>`}${saleStage!=='edit'?receiptTypeSummary():''}<div class="tablewrap"><table class="sale-table"><thead><tr><th>Ürün</th><th>Stok</th><th>Miktar</th><th>Birim fiyat</th><th>Tutar</th><th></th></tr></thead><tbody id="basket">${basketRows()}</tbody></table></div><div class="termfoot sale-footer"><div><small id="sale-count">${basket.length} kalem · ${saleCount()} adet</small><small>Fiş toplamı · onaylı indirim dahil</small><div class="total" id="sale-total">${saleMoney(salesTotal()*100)}</div><small>Tahsilatı İlker ayrıca kaydeder.</small></div><div class="sale-actions">${saleStage==='edit'?`<button class="btn primary" data-wf-click="wf16" ${basket.length?'':'disabled'}>Fişi bitir →</button>`:saleStage==='review'?`<button class="btn" data-wf-click="wf17">Düzenlemeye dön</button><button class="btn primary" data-wf-click="wf18">Örneği tamamla</button>`:`<button class="btn primary" data-wf-click="wf19">Yeni örnek fiş</button><button class="btn" data-wf-click="wf20">Fiş 360’ı aç</button>`}</div></div>${saleStage==='review'?'<div class="sale-info">Canlı bağlantıda tamamlanan fiş, stok çıkışını ve müşteri borcunu birlikte oluşturacak. Örnek kayıt bu tarayıcıda saklanır.</div>':saleStage==='done'?'<div class="sale-info" role="status">Örnek akış tamamlandı. Gerçek stok ve cari bakiyesi değişmedi.</div>':''}</div></div>`}
function basketRows(){return basket.length?basket.map((b,i)=>`<tr><td class="sale-product"><b>${htmlText(b.name)}</b><br><small>${b.code}</small><span class="sale-row-meta">${saleMoney(salePriceCents(b))} · Stok ${b.stock}</span></td><td data-label="Örnek stok">${b.stock} adet</td><td data-label="Miktar">${saleStage==='edit'?`<input aria-label="${b.code} miktar" type="number" min="1" max="1000000" step="1" value="${b.qty}" data-wf-input="wf21" data-wf-arg0="${i}">`:b.qty+' adet'}</td><td data-label="Birim fiyat">${saleMoney(salePriceCents(b))}</td><td data-label="Tutar"><b>${saleMoney(salePriceCents(b)*b.qty)}</b></td><td class="sale-remove">${saleStage==='edit'?`<button class="btn small" aria-label="${b.code} satırını sil" data-wf-click="wf22" data-wf-arg0="${i}">×</button>`:''}</td></tr>`).join(''):`<tr><td colspan="6" class="sale-empty">İlk ürünün barkodunu okut.<br><small>Ürünler burada listelenecek.</small></td></tr>`}
function setSaleQty(index,input){const n=Number(input.value);input.setCustomValidity('');if(!input.value||!Number.isInteger(n)||n<1||n>1000000)input.setCustomValidity('Pozitif tam sayı gir.');else basket[index].qty=n;const ok=[...document.querySelectorAll('.sale-table input')].every(el=>el.checkValidity());document.querySelectorAll('.sale-actions button,.termsearch button').forEach(el=>el.disabled=!ok);document.querySelector('.sale-feedback').textContent=ok?'Miktar güncellendi.':'Miktarı 1–1.000.000 arasında tam sayı olarak gir.';document.getElementById('sale-total').textContent=ok?saleMoney(salesTotal()*100):'—';document.getElementById('sale-count').textContent=basket.length+' kalem · '+saleCount()+' adet';if(input.validity.valid)input.closest('tr').querySelector('[data-label="Tutar"] b').textContent=saleMoney(salePriceCents(basket[index])*n)}
function receiptsPage(){return `${title('SATIŞ BELGELERİ','Satış fişleri','Fişleri personel, tarih, cari veya numarayla bul. Muhasebe fişi gerektiğinde düzeltir; satışçı tamamlanan fişi değiştiremez.','<button class="btn primary" data-wf-click="wf23">＋ Satış fişi</button>')}<div class="grid stats">${stat('Bugün tamamlanan','18 fiş','Satışçı tarafından kapatıldı')}${stat('Muhasebe kontrolü','3 fiş','İade / cari aktarımı')}${stat('Onay bekleyen','2 fiş','İndirim %3 üzeri','warn')}${stat('İptal edilen','4 fiş','İptal nedeni görünür')}</div>${panel('Fiş listesi',`<div class="filters"><input class="search" placeholder="Fiş no, müşteri veya personel ara"><select class="filter"><option>Son 7 gün</option><option>Bugün</option><option>Tüm tarihler</option></select><select class="filter"><option>Tüm durumlar</option><option>Tamamlandı</option><option>İptal</option></select><span class="spacer"></span><button class="btn small" data-wf-click="wf24">Filtrele</button></div><div class="tablewrap"><table><thead><tr><th>Fiş no / saat</th><th>Personel</th><th>Cari</th><th>Ürün / adet</th><th>Tutar</th><th>Durum</th><th></th></tr></thead><tbody><tr data-wf-click="wf25"><td><b>SF-02659</b><br><small>28 Eyl · 11:42</small></td><td>Mehmet</td><td>Peşin Dolar</td><td>20 satır · 134 adet</td><td>1.340 USD</td><td>${badge('Tamamlandı','green')}</td><td>›</td></tr><tr data-wf-click="wf26"><td><b>SF-02658</b><br><small>28 Eyl · 11:18</small></td><td>Veronika</td><td>Peşin Dolar</td><td>8 satır · 42 adet</td><td>468 USD</td><td>${badge('Cari aktarımı','orange')}</td><td>›</td></tr><tr><td><b>SF-02657</b><br><small>28 Eyl · 10:56</small></td><td>Turgay</td><td>Baby Star</td><td>11 satır · 67 adet</td><td>625 EUR</td><td>${badge('İptal · yeniden açıldı','blue')}</td><td>›</td></tr></tbody></table></div>`,'<small>Tıklayınca fiş ayrıntısı</small>')}<div id="receiptDetail"></div>`}
function customersPage(){return `${title('CARİ HESAPLAR','Cariler','Vega 2026 cari kartları · yalnız görüntüleme')}<div id="liveAccounts" class="live-accounts"><section class="card" style="padding:20px" role="status">Cari bağlantısı hazırlanıyor…</section></div>`}
function collectionsPage(){return `${title('PARA TAHSİLATI','Tahsilat kaydet','Gerçek ödeme alındığında muhasebe kaydeder. Satış fişinden ayrı tutulur ve müşterinin genel bakiyesini azaltır.','<button class="btn primary" data-wf-click="wf27">＋ Tahsilat al</button>')}<div class="grid stats">${stat('Bugün alınan','48.250 TL','Nakit, banka, kart')}${stat('Bekleyen bildirim','1 kayıt','Muhasebe doğrulayacak','warn')}${stat('Nakit kasa','₺ 126.400','Güncel bakiye')}${stat('Banka','₺ 482.210','Güncel bakiye')}</div><div class="grid two">${panel('Son tahsilatlar',`<div class="tablewrap"><table><thead><tr><th>Saat / cari</th><th>Yöntem</th><th>Tutar</th><th>Kaydeden</th></tr></thead><tbody><tr><td>11:56 · Alfa Kids</td><td>Nakit</td><td>300 USD</td><td>İlker</td></tr><tr><td>10:28 · Baby Star</td><td>Banka</td><td>200 EUR</td><td>İlker</td></tr><tr><td>09:15 · Mavi Dünya</td><td>Kart / POS</td><td>₺ 8.400</td><td>İlker</td></tr></tbody></table></div>`)}${panel('Ödeme bildirimi',`<div style="padding:17px"><div class="notice amber">Satış personeli 300 USD ödeme bildirimi açtı. Doğrulanana kadar cari ve kasa değişmez.</div><p><b>Alfa Kids · 300 USD · nakit</b><br><small class="sub">Bildiren: Mehmet · 11:51</small></p><button class="btn primary" data-wf-click="wf28">Kontrol et ve kaydet</button> <button class="btn" data-wf-click="wf29">Düzeltme iste</button></div>`,'<small>Onay öncesi</small>')}</div>`}
function countPage(){return `${title('STOK KONTROLÜ','Sayım & düzeltme','Farkı önce araştır. Fiziksel sayım, açıklama ve yetki kontrolünden sonra yalnız fark kadar stok düzeltmesi yapılır.','<button class="btn primary" data-wf-click="wf30">＋ Sayım başlat</button>')}<div class="notice amber"><strong>Bekleyen fark: M-208 · 6 adet.</strong> Nedeni bulunmadan stok düzeltmesi yapılmaz. Büyük fark eşiği henüz tanımlanmadı.</div>${panel('Sayım listesi',`<div class="tablewrap"><table><thead><tr><th>Sayım no</th><th>Ürün</th><th>Sistem</th><th>Fiziksel</th><th>Fark</th><th>Durum</th><th></th></tr></thead><tbody><tr><td>SY-00118</td><td>M-208 · Pamuklu body seti</td><td>24 adet</td><td>18 adet</td><td style="color:var(--red)">−6</td><td>${badge('Araştırılıyor','orange')}</td><td><button class="btn small" data-wf-click="wf31">İncele</button></td></tr><tr><td>SY-00117</td><td>M-100 · Triko bebek takımı</td><td>144 adet</td><td>144 adet</td><td>0</td><td>${badge('Eşleşti','green')}</td><td>—</td></tr></tbody></table></div>`,'<small>İlker sayımı kabul eder</small>')}<div style="height:14px"></div>${panel('Fark araştırma adımları',tasks([['⌗','Ürün ve depo hareketlerini karşılaştır','Son giriş, satış, iade ve aktarım','İncele','blue'],['♙','Ekipten tekrar sayım iste','Belirsiz miktar varsa ikinci sayım','Bekliyor','orange'],['✓','Açıklamayı ve farkı kaydet','Sadece net fark kadar düzelt','Yetkili onayı','green']]))}`}
function returnsPage(){return `${title('İADE VE DÜZELTME','İadeler','Fiziksel ürün dönüşünü satış fişi düzeltmesinden ayrı takip et. Tedarikçiye iade kararını Angela ve Semih verir.','<button class="btn primary" data-wf-click="wf32">＋ İade kaydı</button>')}<div class="grid stats">${stat('Müşteri iadesi','2 kayıt','Muhasebe inceleyecek','warn')}${stat('Tedarikçiye iade','1 karar','Angela + Semih onayı')}${stat('Fiş düzeltme','3 belge','Stok/cari farkı birlikte')}${stat('İade bekleyen miktar','18 adet','Kontrolde')}</div>${panel('İade ve düzeltme kayıtları',`<div class="tablewrap"><table><thead><tr><th>Belge / tür</th><th>İlgili fiş</th><th>Müşteri / tedarikçi</th><th>Miktar</th><th>Neden</th><th>Durum</th></tr></thead><tbody><tr><td>IA-00142 · Müşteri</td><td>SF-02644</td><td>Alfa Kids</td><td>6 adet</td><td>Yanlış model</td><td>${badge('Ürün sayımı','orange')}</td></tr><tr><td>IA-00141 · Tedarikçi</td><td>MK-00402</td><td>Concept</td><td>12 adet</td><td>Defolu ürün</td><td>${badge('Karar bekliyor','blue')}</td></tr><tr><td>DZ-00087 · Fiş düzeltme</td><td>SF-02631</td><td>Peşin Dolar → Alfa Kids</td><td>30 adet</td><td>Gerçek müşteri carisine aktar</td><td>${badge('İlker inceliyor','orange')}</td></tr></tbody></table></div>`,'<small>Miktar ve cari etkisi izlenir</small>')}<div class="notice">Cari aktarımında eski ve yeni fiş bağlantısı saklanır. Satış borcu iki kez oluşmaz; tahsilat varsa ayrıca uzlaştırılır.</div>`}
