function showProduct(i){let p=stock[i];document.querySelectorAll('#stocktable tbody tr').forEach((r,index)=>{r.classList.toggle('selected',index===i);r.setAttribute('aria-selected',String(index===i))});document.getElementById('productDetail').innerHTML=`<section class="card inspector-card"><header><div><div class="eyebrow">SEÇİLİ ÜRÜN · ${p[0]}</div><h2>${htmlText(p[1])}</h2></div><button class="btn small" aria-label="Ürün ayrıntısını kapat" data-wf-click="wf36">×</button></header><p class="sub">${htmlText(p[2])}</p><div class="inspector-metrics"><div><small>Mevcut stok</small><strong>${p[3]} <span>adet</span></strong></div><div><small>Son alış</small><strong>${fmt(p[4])} <span>USD</span></strong></div></div><dl><div><dt>Model kodu</dt><dd>${p[0]}</dd></div><div><dt>Durum</dt><dd>${badge(p[5],p[5]==='Kritik'?'red':p[5]==='Az stok'?'orange':'green')}</dd></div></dl><h3>Son hareket</h3><div class="notice">Satış fişi SF-02659<br><b>−12 adet</b> · Bugün 11:42</div><p class="sub">Satış fiyatını İlker ve Angela belirler.</p><div class="inspector-foot">Örnek kayıt · Tasarım önizlemesi</div></section>`;}
function filterTable(q){document.querySelectorAll('#stocktable tbody tr').forEach(r=>r.style.display=r.innerText.toLowerCase().includes(q.toLowerCase())?'':'none')}
function addProduct(){if(saleStage!=='edit'||[...document.querySelectorAll('.sale-table input')].some(el=>!el.checkValidity()))return;const input=document.getElementById('scan'),q=input.value.trim();const codes={'8690000000101':'M-100','8690000000149':'M-142'};const model=codes[q]||q;const p=stock.find(x=>x[0].toLowerCase()===model.toLowerCase()||x[7]?.barcode===q);if(!p){saleMessage=q?'Ürün bulunamadı. Barkodu veya model kodunu kontrol et.':'Önce barkod okut veya model kodu gir.';render();document.getElementById('scan').focus();return}const found=basket.find(x=>x.code===p[0]);if(found){if(found.qty>=1000000){saleMessage='Miktar sınırına ulaşıldı.';render();return}found.qty++}else basket.push({code:p[0],name:p[1],stock:p[3],price:p[4],qty:1,category:p[6]});saleMessage=p[0]+' eklendi. Miktarı gir; Enter ile barkoda dön.';render();const qty=document.querySelector('[aria-label="'+p[0]+' miktar"]');qty?.focus();qty?.select()}
function finishSale(){if(saleStage!=='edit'||!basket.length)return;if(!Number.isFinite(salesTotal())){saleMessage='Geçerli bir döviz kuru girin.';render();return;}const invalid=[...document.querySelectorAll('.sale-table input')].find(el=>!el.checkValidity());if(invalid){invalid.reportValidity();invalid.focus();return}saleStage='review';saleMessage='';render()}
