 modal.querySelector('#product-manual-size').onchange=e=>{const on=e.target.checked;manual.hidden=!on;manual.disabled=!on;template.hidden=on;template.disabled=on;chips.hidden=on;chips.querySelectorAll('input').forEach(el=>el.disabled=on);if(on)manual.focus()};
 modal.querySelector('form').onsubmit=e=>{e.preventDefault();const name=modal.querySelector('#product-name');if(!name.value.trim()){name.setCustomValidity('Ürün adını girin.');name.reportValidity();return}const feedback=modal.querySelector('#product-form-feedback');feedback.hidden=false;try{const data=new FormData(e.target);const code=window.MelisaDemoOperations.saveProduct({name:name.value,brand:data.get('brand'),sizes:data.get('manualSizes')||data.getAll('sizes').join(', '),category:data.get('category'),barcode:data.get('barcode'),note:data.get('note')});feedback.textContent=code+' örnek ürün kartı kaydedildi.';e.target.querySelector('[type=submit]').disabled=true}catch(error){feedback.textContent=error.message}};
 modal.querySelector('#product-name').oninput=e=>e.target.setCustomValidity('');
 modal.onkeydown=e=>{if(e.key!=='Tab')return;const nodes=[...modal.querySelectorAll('input,select,textarea,button')].filter(el=>!el.disabled&&el.getClientRects().length);const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}};
